-- Rebuild Medina Book 3 lesson 17 strictly from the supplied Arabic sharh.
-- The sharh combines lessons 16-17 under one heading. Lesson 17 begins at "ثانياً: باب أفعل" on PDF page 68 and ends with the final grammar analysis on PDF page 73.
-- The author's closing prayer and decorative marks are not grammar rules and are intentionally excluded.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 68-73.
-- Five Qur'anic strings hidden by DOC control characters were transcribed literally from visible PDF pages 70-71.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17';
  if old_rule_count <> 7 then raise exception 'Expected 7 generated Book 3 lesson 17 rules, found %', old_rule_count; end if;

  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values
    ('Мединский курс (Том 3)', '17', 'بَابُ أَفْعَلَ وَمَصْدَرُهُ (модель أَفْعَلَ и её масдар)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Основа модели</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْبَيَانُ</span><span class="rule-table-ru">пункт</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقَاعِدَةُ</span><span class="rule-table-ru">правило и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِنْ أَمْثِلَتِهِ</span><span class="rule-table-ru">примеры модели</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَسْلَمَ، أَجَابَ، أَتَمَّ، آمَنَ</span><span class="rule-table-ru">принял ислам; ответил; завершил; уверовал</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفُ الزِّيَادَةِ</span><span class="rule-table-ru">добавочная буква</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْهَمْزَةُ فِي أَوَّلِهِ</span><span class="rule-table-ru">хамза в начале глагола</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِفْعَالٌ</span><span class="rule-table-ru">вес «иф‘аль»</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Основные примеры масдара</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ</span><span class="rule-table-ru">глагол и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَصْلُ وَالتَّغْيِيرُ</span><span class="rule-table-ru">исходная форма и изменение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَسْلَمَ</span><span class="rule-table-ru">принял ислам</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِسْلَامٌ</span><span class="rule-table-ru">принятие ислама</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَلَى وَزْنِ إِفْعَالٍ</span><span class="rule-table-ru">на весе «иф‘аль»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَتَمَّ</span><span class="rule-table-ru">завершил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِتْمَامٌ</span><span class="rule-table-ru">завершение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَلَى وَزْنِ إِفْعَالٍ</span><span class="rule-table-ru">на весе «иф‘аль»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">آمَنَ</span><span class="rule-table-ru">уверовал</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِيمَانٌ</span><span class="rule-table-ru">вера</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَصْلُهُ إِئْمَانٌ؛ قُلِبَتِ الْهَمْزَةُ يَاءً لِأَنَّهَا سَاكِنَةٌ وَمَا قَبْلَهَا مَكْسُورٌ</span><span class="rule-table-ru">исходная форма «и’ман»; хамза заменена на йа, потому что она с сукуном, а перед ней касра</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Изменения у слабых глаголов</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الِاعْتِلَالِ</span><span class="rule-table-ru">место слабой коренной</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفِعْلُ</span><span class="rule-table-ru">глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَصْلُ</span><span class="rule-table-ru">исходная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّغْيِيرُ</span><span class="rule-table-ru">изменение и причина</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلُّ الْفَاءِ</span><span class="rule-table-ru">слабая первая коренная</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَوْجَدَ</span><span class="rule-table-ru">создал; обнаружил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِيجَادٌ</span><span class="rule-table-ru">создание; нахождение</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِوْجَادٌ</span><span class="rule-table-ru">исходная форма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قُلِبَتِ الْوَاوُ يَاءً؛ لِأَنَّهَا سَاكِنَةٌ وَمَا قَبْلَهَا مَكْسُورٌ، وَالْكَسْرُ يُنَاسِبُهُ الْيَاءُ</span><span class="rule-table-ru">вау заменена на йа: она с сукуном после касры, которой соответствует йа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلُّ الْعَيْنِ</span><span class="rule-table-ru">слабая вторая коренная</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَجَابَ</span><span class="rule-table-ru">ответил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِجَابَةٌ</span><span class="rule-table-ru">ответ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِجْوَابٌ</span><span class="rule-table-ru">исходная форма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حُذِفَتْ عَيْنُ الْمَصْدَرِ، وَهِيَ الْوَاوُ، وَعُوِّضَ عَنْهَا بِتَاءِ التَّأْنِيثِ</span><span class="rule-table-ru">вторая коренная масдара — вау — удалена и возмещена та женского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلُّ اللَّامِ</span><span class="rule-table-ru">слабая третья коренная</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَلْقَى</span><span class="rule-table-ru">бросил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِلْقَاءٌ</span><span class="rule-table-ru">бросание</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِلْقَايٌ</span><span class="rule-table-ru">исходная форма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قُلِبَتِ الْيَاءُ هَمْزَةً؛ لِأَنَّهَا وَقَعَتْ مُتَطَرِّفَةً وَقَبْلَهَا أَلِفٌ زَائِدَةٌ</span><span class="rule-table-ru">конечная йа заменена на хамзу, поскольку перед ней стоит добавочная алиф</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'В модели «аф‘аля» добавочной является начальная хамза, а основной вес масдара — «иф‘аль»; шарх отдельно показывает изменения при слабой первой, второй или третьей коренной.', 'حَرْفُ الزِّيَادَةِ فِي بَابِ أَفْعَلَ الْهَمْزَةُ فِي أَوَّلِهِ، وَمَصْدَرُهُ فِي الْأَصْلِ عَلَى وَزْنِ إِفْعَالٍ. تَتَغَيَّرُ صِيغَةُ الْمَصْدَرِ إِذَا كَانَ الْفِعْلُ مُعْتَلَّ الْفَاءِ أَوِ الْعَيْنِ أَوِ اللَّامِ وَفْقَ مَا بَيَّنَهُ الْمُؤَلِّفُ.'),
    ('Мединский курс (Том 3)', '17', 'مُشْتَقَّاتُ بَابِ أَفْعَلَ وَحَذْفُ هَمْزَةِ الْمُضَارَعَةِ (производные формы أَفْعَلَ и удаление хамзы настоящего времени)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Производные формы بَابِ أَفْعَلَ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настоящее-будущее</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повеление</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمُ الْفَاعِلِ</span><span class="rule-table-ru">имя действующего</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمُ الْمَفْعُولِ</span><span class="rule-table-ru">имя объекта действия</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَكْرَمَ</span><span class="rule-table-ru">оказал почёт</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُكْرِمُ</span><span class="rule-table-ru">оказывает почёт</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَكْرِمْ</span><span class="rule-table-ru">окажи почёт</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِكْرَامٌ</span><span class="rule-table-ru">оказание почёта</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُكْرِمٌ</span><span class="rule-table-ru">оказывающий почёт</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُكْرَمٌ</span><span class="rule-table-ru">тот, кому оказан почёт</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَقَامَ</span><span class="rule-table-ru">установил; пребывал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُقِيمُ</span><span class="rule-table-ru">устанавливает; пребывает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَقِمْ</span><span class="rule-table-ru">установи</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِقَامَةٌ</span><span class="rule-table-ru">пребывание; установление</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُقِيمٌ</span><span class="rule-table-ru">пребывающий</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُقَامٌ</span><span class="rule-table-ru">установленный; место пребывания</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَبْكَى</span><span class="rule-table-ru">заставил плакать</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُبْكِي</span><span class="rule-table-ru">заставляет плакать</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَبْكِ</span><span class="rule-table-ru">заставь плакать</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِبْكَاءٌ</span><span class="rule-table-ru">принуждение к плачу</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْكٍ</span><span class="rule-table-ru">заставляющий плакать</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُبْكًى</span><span class="rule-table-ru">тот, кого заставили плакать</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَوْقَفَ</span><span class="rule-table-ru">остановил</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُوقِفُ</span><span class="rule-table-ru">останавливает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَوْقِفْ</span><span class="rule-table-ru">останови</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِيقَافٌ</span><span class="rule-table-ru">остановка</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُوقِفٌ</span><span class="rule-table-ru">останавливающий</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُوقَفٌ</span><span class="rule-table-ru">остановленный</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">إِذَا كَانَ الْمَاضِي عَلَى وَزْنِ <span class="ar-tone-verb">أَفْعَلَ</span> وَجَبَ حَذْفُ هَمْزَةِ الْبَابِ مِنْ مُضَارِعِ الْمُتَكَلِّمِ؛ كَرَاهَةَ اجْتِمَاعِ هَمْزَتَيْنِ.</span><p class="rule-study-text">У глагола модели «аф‘аля» в форме настоящего времени первого лица удаляется хамза модели, чтобы избежать встречи двух хамз.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Форма первого лица</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَارِعُ الصَّحِيحُ</span><span class="rule-table-ru">правильная форма настоящего</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَصْلُ</span><span class="rule-table-ru">исходная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَبَبُ الْحَذْفِ</span><span class="rule-table-ru">причина удаления</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَكْرَمَ</span><span class="rule-table-ru">оказал почёт</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أُكْرِمُ</span><span class="rule-table-ru">я оказываю почёт</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أُأَكْرِمُ</span><span class="rule-table-ru">исходная форма с двумя хамзами</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَرَاهَةُ اجْتِمَاعِ هَمْزَتَيْنِ</span><span class="rule-table-ru">нежелательность соединения двух хамз</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Остальные формы, на которые перенесено изменение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُكْرِمُ</span><span class="rule-table-ru">он оказывает почёт</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نُكْرِمُ</span><span class="rule-table-ru">мы оказываем почёт</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تُكْرِمُ</span><span class="rule-table-ru">ты или она оказывает почёт</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُكْرِمٌ</span><span class="rule-table-ru">оказывающий почёт</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُكْرَمٌ</span><span class="rule-table-ru">тот, кому оказан почёт</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حُمِلَ ذَلِكَ عَلَى بَقِيَّةِ التَّصَارِيفِ</span><span class="rule-table-ru">это распространено на остальные производные формы</span></td></tr></tbody></table></div></div></div>', 2, 'rule', 'У глагола модели «аф‘аля» хамза модели удаляется в форме настоящего времени первого лица, чтобы не соединять две хамзы; это изменение распространяется и на остальные производные формы.', 'إِذَا كَانَ الْفِعْلُ الْمَاضِي عَلَى وَزْنِ أَفْعَلَ وَجَبَ حَذْفُ هَمْزَةِ الْبَابِ مِنْ مُضَارِعِ الْمُتَكَلِّمِ كَرَاهَةَ اجْتِمَاعِ هَمْزَتَيْنِ، وَحُمِلَ عَلَى ذَلِكَ بَقِيَّةُ التَّصَارِيفِ.'),
    ('Мединский курс (Том 3)', '17', 'أَعْطَى وَنَصْبُ مَفْعُولَيْنِ (глагол أَعْطَى и два прямых дополнения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-verb">أَعْطَى</span> مِنْ بَابِ أَفْعَلَ، وَيَنْصِبُ <span class="ar-tone-nasb">مَفْعُولَيْنِ</span> لَيْسَ أَصْلُهُمَا الْمُبْتَدَأَ وَالْخَبَرَ.</span><p class="rule-study-text">«А‘та» относится к модели «аф‘аля» и требует двух прямых дополнений, которые изначально не являются парой мубтада и хабар.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Пример с двумя явными дополнениями</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجُمْلَةُ</span><span class="rule-table-ru">предложение и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعُنْصُرُ</span><span class="rule-table-ru">элемент</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَعْطَيْتُ حَامِدًا كِتَابًا.</span><span class="rule-table-ru">Я дал Хамиду книгу.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">حَامِدًا</span><span class="rule-table-ru">Хамиду</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ أَوَّلٌ مَنْصُوبٌ</span><span class="rule-table-ru">первое прямое дополнение в винительном падеже</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَعْطَيْتُ حَامِدًا كِتَابًا.</span><span class="rule-table-ru">Я дал Хамиду книгу.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">كِتَابًا</span><span class="rule-table-ru">книгу</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ ثَانٍ مَنْصُوبٌ</span><span class="rule-table-ru">второе прямое дополнение в винительном падеже</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Пример с присоединёнными местоимениями</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجُمْلَةُ</span><span class="rule-table-ru">предложение и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعُنْصُرُ</span><span class="rule-table-ru">элемент</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَعْطَانِيهِ الْمُدِيرُ.</span><span class="rule-table-ru">Директор дал мне это.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">يَاءُ الْمُتَكَلِّمِ</span><span class="rule-table-ru">местоимение «мне»</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ أَوَّلٌ</span><span class="rule-table-ru">в синтаксическом месте первого прямого дополнения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَعْطَانِيهِ الْمُدِيرُ.</span><span class="rule-table-ru">Директор дал мне это.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْهَاءُ</span><span class="rule-table-ru">местоимение «это; его»</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ ثَانٍ</span><span class="rule-table-ru">в синтаксическом месте второго прямого дополнения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَعْطَانِيهِ الْمُدِيرُ.</span><span class="rule-table-ru">Директор дал мне это.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُدِيرُ</span><span class="rule-table-ru">директор</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">فَاعِلٌ مَرْفُوعٌ</span><span class="rule-table-ru">исполнитель действия в именительном падеже</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'Глагол «а‘та» относится к модели «аф‘аля» и ставит в винительный падеж два прямых дополнения, которые не восходят к мубтада и хабару.', 'أَعْطَى مِنْ بَابِ أَفْعَلَ، وَهُوَ يَنْصِبُ مَفْعُولَيْنِ لَيْسَ أَصْلُهُمَا الْمُبْتَدَأَ وَالْخَبَرَ.'),
    ('Мединский курс (Том 3)', '17', 'أَصْبَحَ: مِنْ أَخَوَاتِ كَانَ وَبِمَعْنَى صَارَ (أَصْبَحَ как сестра كَانَ и в значении «стал»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-verb">أَصْبَحَ</span> مِنْ أَخَوَاتِ كَانَ؛ <span class="ar-tone-raf">يَرْفَعُ الِاسْمَ</span> وَ<span class="ar-tone-nasb">يَنْصِبُ الْخَبَرَ</span>.</span><p class="rule-study-text">«Асбаха» относится к сёстрам «кана»: её имя стоит в именительном, а хабар — в винительном падеже.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Значение наступления утра</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى الَّذِي ذَكَرَهُ الْمُؤَلِّفُ</span><span class="rule-table-ru">толкование автора</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَصْبَحَ حَامِدٌ مَرِيضًا.</span><span class="rule-table-ru">Хамид оказался утром больным.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَدْرَكَهُ الصَّبَاحُ وَهُوَ مَرِيضٌ</span><span class="rule-table-ru">утро застало его больным</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَصْبَحَ الْبَرْدُ شَدِيدًا.</span><span class="rule-table-ru">К утру холод стал сильным.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَصْبَحَ مِنْ أَخَوَاتِ كَانَ</span><span class="rule-table-ru">«асбаха» действует как «кана»</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-verb" dir="rtl" lang="ar">﴿ وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَى فَارِغًا ﴾</span><span class="rule-example-ru">«Сердце матери Мусы опустело».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">قَدْ تَأْتِي <span class="ar-tone-verb">أَصْبَحَ</span> بِمَعْنَى <span class="ar-tone-verb">صَارَ</span>.</span><p class="rule-study-text">«Асбаха» может употребляться в значении «стал; превратился».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-verb" dir="rtl" lang="ar">﴿ فَأَصْبَحْتُمْ بِنِعْمَتِهِ إِخْوَانًا ﴾</span><span class="rule-example-ru">«И по Его милости вы стали братьями».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Толкование автора</span><p class="rule-study-text"><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">أَيْ: صِرْتُمْ إِخْوَانًا.</span> То есть: вы стали братьями.</p></div></div>', 4, 'rule', '«Асбаха» действует как «кана»: поднимает имя и ставит хабар в винительный падеж; оно может означать наступление утра либо переход в новое состояние — «стал».', 'أَصْبَحَ مِنْ أَخَوَاتِ كَانَ؛ يَرْفَعُ الِاسْمَ وَيَنْصِبُ الْخَبَرَ. يَدُلُّ عَلَى دُخُولِ الصَّبَاحِ، وَقَدْ يَأْتِي بِمَعْنَى صَارَ.'),
    ('Мединский курс (Том 3)', '17', 'أَوْشَكَ مِنْ أَفْعَالِ الْمُقَارَبَةِ (أَوْشَكَ — глагол приближения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-verb">أَوْشَكَ</span> مِنْ أَفْعَالِ الْمُقَارَبَةِ؛ يَعْمَلُ عَمَلَ كَانَ، فَيَرْفَعُ الِاسْمَ وَيَنْصِبُ الْخَبَرَ.</span><p class="rule-study-text">«Аушака» относится к глаголам приближения и действует как «кана»: имя ставит в именительный, хабар — в винительный падеж.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">خَبَرُ أَوْشَكَ لَا يَكُونُ إِلَّا <span class="ar-tone-predicate">جُمْلَةً فِعْلِيَّةً</span> فِعْلُهَا <span class="ar-tone-verb">مُضَارِعٌ مُقْتَرِنٌ بِأَنْ الْمَصْدَرِيَّةِ</span>.</span><p class="rule-study-text">Хабар «аушака» бывает только глагольным предложением: его глагол — форма настоящего-будущего времени с масдарной «ан».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">خَبَرُ أَوْشَكَ</span><span class="rule-table-ru">хабар «аушака»</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَوْشَكَ الْمَطَرُ أَنْ يَنْزِلَ.</span><span class="rule-table-ru">Дождь вот-вот пойдёт.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">أَنْ يَنْزِلَ</span><span class="rule-table-ru">что он пойдёт</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُوشِكُ الطُّلَّابُ أَنْ يَتَخَرَّجُوا.</span><span class="rule-table-ru">Студенты скоро выпустятся.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">أَنْ يَتَخَرَّجُوا</span><span class="rule-table-ru">что они выпустятся</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор أَوْشَكَ الدَّرْسُ أَنْ يَنْتَهِيَ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعُنْصُرُ</span><span class="rule-table-ru">элемент</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَوْشَكَ</span><span class="rule-table-ru">вот-вот</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مَاضٍ نَاقِصٌ مَبْنِيٌّ عَلَى الْفَتْحِ.</span><span class="rule-table-ru">недостаточный глагол прошедшего времени, построенный на фатхе</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مِنْ أَفْعَالِ الْمُقَارَبَةِ</span><span class="rule-table-ru">глагол приближения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الدَّرْسُ</span><span class="rule-table-ru">урок</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">اِسْمُ أَوْشَكَ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">имя «аушака» в именительном падеже; признак — явная дамма</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اِسْمُ أَوْشَكَ</span><span class="rule-table-ru">имя «аушака»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنْ</span><span class="rule-table-ru">масдарная «ан»</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">حَرْفُ نَصْبٍ وَمَصْدَرٍ مَبْنِيٌّ عَلَى السُّكُونِ.</span><span class="rule-table-ru">частица винительного управления и образования масдара, построенная на сукуне</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ نَصْبٍ وَمَصْدَرٍ</span><span class="rule-table-ru">частица насба и масдара</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَنْتَهِيَ</span><span class="rule-table-ru">закончится</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَنْصُوبٌ بِأَنْ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">глагол настоящего-будущего времени в винительном состоянии после «ан»; признак — явная фатха</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَنْصُوبٌ</span><span class="rule-table-ru">глагол настоящего-будущего времени в насбе</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">أَنْ يَنْتَهِيَ</span><span class="rule-table-ru">что закончится</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَصْدَرُ الْمُؤَوَّلُ فِي مَحَلِّ نَصْبٍ خَبَرُ أَوْشَكَ.</span><span class="rule-table-ru">развёрнутый масдар находится в синтаксическом месте винительного падежа как хабар «аушака»</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُ أَوْشَكَ</span><span class="rule-table-ru">хабар «аушака»</span></td></tr></tbody></table></div></div></div>', 5, 'rule', '«Аушака» — глагол приближения, действующий как «кана»; его хабар бывает только глагольным предложением с настоящим-будущим глаголом после масдарной «ан».', 'أَوْشَكَ مِنْ أَفْعَالِ الْمُقَارَبَةِ، وَهُوَ يَعْمَلُ عَمَلَ كَانَ فَيَرْفَعُ الِاسْمَ وَيَنْصِبُ الْخَبَرَ، إِلَّا أَنَّ خَبَرَهُ لَا يَكُونُ إِلَّا جُمْلَةً فِعْلِيَّةً فِعْلُهَا مُضَارِعٌ مُقْتَرِنٌ بِأَنْ الْمَصْدَرِيَّةِ.'),
    ('Мединский курс (Том 3)', '17', 'وَلَوْ وَالْجُمْلَةُ الْحَالِيَّةُ (وَلَوْ и обстоятельственное предложение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-structure" dir="rtl" lang="ar">﴿ وَاللَّهُ مُتِمُّ نُورِهِ وَلَوْ كَرِهَ الْكَافِرُونَ ﴾</span><span class="rule-example-ru">«Аллах завершит Свой свет, даже если это ненавистно неверующим».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор وَلَوْ كَرِهَ الْكَافِرُونَ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعُنْصُرُ</span><span class="rule-table-ru">элемент</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْوَاوُ</span><span class="rule-table-ru">вау</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لِلْحَالِ، حَرْفٌ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">вау обстоятельства; частица, построенная на фатхе, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">وَاوُ الْحَالِ</span><span class="rule-table-ru">вау обстоятельства</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْ</span><span class="rule-table-ru">если бы; даже если</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ شَرْطٍ غَيْرُ جَازِمٍ مَبْنِيٌّ عَلَى السُّكُونِ.</span><span class="rule-table-ru">неуправляющая условная частица, построенная на сукуне</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">لَا تَجْزِمُ</span><span class="rule-table-ru">не управляет джазмом</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَرِهَ</span><span class="rule-table-ru">возненавидел</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلُ الشَّرْطِ، فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى الْفَتْحِ.</span><span class="rule-table-ru">глагол условия; прошедший глагол, построенный на фатхе</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلُ الشَّرْطِ</span><span class="rule-table-ru">глагол условия</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">جَوَابُ الشَّرْطِ</span><span class="rule-table-ru">ответ условия</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَحْذُوفٌ.</span><span class="rule-table-ru">опущен</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَالتَّقْدِيرُ: وَلَوْ كَرِهَ الْكَافِرُونَ فَإِنَّ اللَّهَ مُتِمُّ نُورِهِ.</span><span class="rule-table-ru">подразумевается: даже если неверующие ненавидят это, Аллах завершит Свой свет</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَوْ كَرِهَ الْكَافِرُونَ</span><span class="rule-table-ru">если даже неверующие ненавидят</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">جُمْلَةُ الشَّرْطِ فِي مَحَلِّ نَصْبٍ حَالًا.</span><span class="rule-table-ru">условное предложение находится в синтаксическом месте винительного падежа как обстоятельство состояния</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">حَالٌ</span><span class="rule-table-ru">обстоятельство состояния</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Другие примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">صَلِّ وَلَوْ كُنْتَ مَرِيضًا.</span><span class="rule-table-ru">Молись, даже если ты болен.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَنْ أَشْرَبَ الْخَمْرَ وَلَوْ عَذَّبْتَنِي.</span><span class="rule-table-ru">Я не стану пить вино, даже если ты подвергнешь меня мучению.</span></td></tr></tbody></table></div></div></div>', 6, 'rule', 'В сочетании «ва-лау» вау вводит обстоятельство, а «лау» является неуправляющей условной частицей; условное предложение может занимать место обстоятельства в винительном падеже.', 'فِي وَلَوْ تَكُونُ الْوَاوُ لِلْحَالِ، وَلَوْ حَرْفُ شَرْطٍ غَيْرُ جَازِمٍ. قَدْ يُحْذَفُ جَوَابُ الشَّرْطِ، وَتَكُونُ جُمْلَةُ الشَّرْطِ فِي مَحَلِّ نَصْبٍ حَالًا.'),
    ('Мединский курс (Том 3)', '17', 'لَامُ الِابْتِدَاءِ (лям начала для усиления)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-particle">لَامُ الِابْتِدَاءِ</span> حَرْفُ ابْتِدَاءٍ يَقَعُ فِي ابْتِدَاءِ الْكَلَامِ، وَفَائِدَتُهُ <span class="ar-tone-structure">التَّوْكِيدُ</span>.</span><p class="rule-study-text">Лям начала стоит в начале высказывания и служит для усиления его содержания.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ وَلَأَجْرُ الْآخِرَةِ أَكْبَرُ ﴾</span><span class="rule-example-ru">«А награда Последней жизни — больше».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ وَلَذِكْرُ اللَّهِ أَكْبَرُ ﴾</span><span class="rule-example-ru">«А поминание Аллаха — больше».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَامُ الِابْتِدَاءِ</span><span class="rule-table-ru">лям усиления</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَهَذَا طَالِبٌ مُجْتَهِدٌ.</span><span class="rule-table-ru">Воистину, это усердный студент.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَـ</span><span class="rule-table-ru">лям в начале указательного имени</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَفَاطِمَةُ مُؤْمِنَةٌ.</span><span class="rule-table-ru">Воистину, Фатима — верующая.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَـ</span><span class="rule-table-ru">лям перед именем Фатима</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор لَمُحَمَّدٌ مُجْتَهِدٌ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعُنْصُرُ</span><span class="rule-table-ru">элемент</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">اللَّامُ</span><span class="rule-table-ru">лям</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ ابْتِدَاءٍ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица начала, построенная на фатхе, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَامُ الِابْتِدَاءِ</span><span class="rule-table-ru">лям начала</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُحَمَّدٌ</span><span class="rule-table-ru">Мухаммад</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">мубтада в именительном падеже; признак — явная дамма</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-table-ru">мубтада</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُجْتَهِدٌ</span><span class="rule-table-ru">усердный</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">خَبَرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">хабар в именительном падеже; признак — явная дамма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-table-ru">хабар</span></td></tr></tbody></table></div></div></div>', 7, 'rule', 'Лям начала входит в начало высказывания и усиливает содержание всего предложения.', 'لَامُ الِابْتِدَاءِ حَرْفُ ابْتِدَاءٍ يَقَعُ فِي ابْتِدَاءِ الْكَلَامِ، وَفَائِدَتُهُ التَّوْكِيدُ؛ فَهُوَ يُؤَكِّدُ مَضْمُونَ الْجُمْلَةِ.'),
    ('Мединский курс (Том 3)', '17', 'مَا النَّكِرَةُ التَّامَّةُ الْمُبْهَمَةُ (неопределённое مَا в роли определения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-particle">مَا النَّكِرَةُ التَّامَّةُ الْمُبْهَمَةُ</span> اِسْمٌ مَبْنِيٌّ عَلَى السُّكُونِ يَقَعُ <span class="ar-tone-structure">نَعْتًا لِمَا قَبْلَهُ</span>.</span><p class="rule-study-text">Полное неопределённое «ма» — имя, построенное на сукуне; оно является определением предыдущего слова.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры и синтаксические места</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَوْقِعُ مَا</span><span class="rule-table-ru">синтаксическое место «ма»</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">роль</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَدَثَ شَيْءٌ مَا.</span><span class="rule-table-ru">Произошло нечто.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">فِي مَحَلِّ رَفْعٍ</span><span class="rule-table-ru">в синтаксическом месте именительного падежа</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَعْتٌ</span><span class="rule-table-ru">определение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَعْطِنِي كِتَابًا مَا.</span><span class="rule-table-ru">Дай мне какую-нибудь книгу.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِي مَحَلِّ نَصْبٍ</span><span class="rule-table-ru">в синтаксическом месте винительного падежа</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَعْتٌ</span><span class="rule-table-ru">определение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">رَأَيْتُهُ فِي مَكَانٍ مَا.</span><span class="rule-table-ru">Я видел его в каком-то месте.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">فِي مَحَلِّ جَرٍّ</span><span class="rule-table-ru">в синтаксическом месте родительного падежа</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَعْتٌ</span><span class="rule-table-ru">определение</span></td></tr></tbody></table></div></div></div>', 8, 'rule', 'Полное неопределённое «ма» — неизменяемое имя на сукуне, которое служит определением предыдущего слова и следует его синтаксическому месту.', 'مَا النَّكِرَةُ التَّامَّةُ الْمُبْهَمَةُ ٱسْمٌ مَبْنِيٌّ عَلَى السُّكُونِ يَقَعُ نَعْتًا لِمَا قَبْلَهُ، وَيَكُونُ فِي مَحَلِّ رَفْعٍ أَوْ نَصْبٍ أَوْ جَرٍّ بِحَسَبِ الْمَنْعُوتِ.'),
    ('Мединский курс (Том 3)', '17', 'حَذْفُ هَمْزَةِ ٱبْنٍ (удаление хамзы в слове اِبْنٌ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">تُحْذَفُ هَمْزَةُ <span class="ar-tone-structure">ٱبْنٍ</span> إِذَا وَقَعَتِ الْكَلِمَةُ <span class="ar-tone-structure">صِفَةً بَيْنَ عَلَمَيْنِ</span>، الْأَوَّلُ الِابْنُ وَالثَّانِي الْأَبُ، وَكَانَتِ الْكَلِمَاتُ الثَّلَاثُ <span class="ar-tone-structure">فِي سَطْرٍ وَاحِدٍ</span>.</span><p class="rule-study-text">Хамза «ибн» удаляется на письме, если слово является определением между двумя именами — сына и отца — и все три слова стоят в одной строке.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры удаления хамзы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَبَبُ الْحَذْفِ</span><span class="rule-table-ru">почему хамза удалена</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ.</span><span class="rule-table-ru">Это Мухаммад, сын Абдуллаха, сына Абд аль-Мутталиба.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صِفَةٌ بَيْنَ عَلَمَيْنِ فِي سَطْرٍ وَاحِدٍ</span><span class="rule-table-ru">определение между именами в одной строке</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">رَأَيْتُ سَعِيدَ بْنَ حَامِدٍ.</span><span class="rule-table-ru">Я видел Саида, сына Хамида.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صِفَةٌ بَيْنَ عَلَمَيْنِ فِي سَطْرٍ وَاحِدٍ</span><span class="rule-table-ru">определение между именами в одной строке</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَلَّمْتُ عَلَى خَالِدِ بْنِ عَلِيٍّ.</span><span class="rule-table-ru">Я поприветствовал Халида, сына Али.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صِفَةٌ بَيْنَ عَلَمَيْنِ فِي سَطْرٍ وَاحِدٍ</span><span class="rule-table-ru">определение между именами в одной строке</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три случая сохранения хамзы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">случай</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعْلِيلُ</span><span class="rule-table-ru">объяснение автора</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَمْ تَقَعْ صِفَةً</span><span class="rule-table-ru">слово не является определением</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَامِدٌ ٱبْنُ عَلِيٍّ.</span><span class="rule-table-ru">Хамид — сын Али.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">اِبْنُ: خَبَرٌ مَرْفُوعٌ</span><span class="rule-table-ru">«ибн» — хабар в именительном падеже</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَاءَتْ فِي أَوَّلِ السَّطْرِ</span><span class="rule-table-ru">слово оказалось в начале строки</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">السَّطْرُ الْأَوَّلُ: رَأَيْتُ مُحَمَّدًا. السَّطْرُ الثَّانِي: اِبْنَ سَعِيدٍ.</span><span class="rule-table-ru">Первая строка: «Я видел Мухаммада». Вторая строка: «сына Саида».</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَلَوْ كَانَتْ بَيْنَ عَلَمَيْنِ</span><span class="rule-table-ru">даже если оно находится между двумя именами</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَمْ تَقَعْ بَيْنَ عَلَمَيْنِ</span><span class="rule-table-ru">слово не находится между двумя именами</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَامِدٌ ٱبْنُ الشَّيْخِ إِبْرَاهِيمَ.</span><span class="rule-table-ru">Хамид — сын шейха Ибрахима.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَلِمَةُ الشَّيْخِ لَيْسَتْ عَلَمًا</span><span class="rule-table-ru">слово «шейх» не является собственным именем</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор هَذَا مُحَمَّدُ بْنُ حَامِدٍ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">полный разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">هَذَا</span><span class="rule-table-ru">это</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">اِسْمُ إِشَارَةٍ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ مُبْتَدَأٌ.</span><span class="rule-table-ru">указательное имя, построенное на сукуне, в синтаксическом месте именительного падежа как мубтада</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-table-ru">мубтада</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُحَمَّدُ</span><span class="rule-table-ru">Мухаммад</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">خَبَرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ. حُذِفَ تَنْوِينُهُ تَخْفِيفًا.</span><span class="rule-table-ru">хабар в именительном падеже; признак — явная дамма; танвин удалён для облегчения</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-table-ru">хабар</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بْنُ</span><span class="rule-table-ru">сын</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">صِفَةٌ مَرْفُوعَةٌ، وَعَلَامَةُ رَفْعِهَا الضَّمَّةُ الظَّاهِرَةُ، وَهُوَ مُضَافٌ.</span><span class="rule-table-ru">определение в именительном падеже; признак — явная дамма; является первым членом идафы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صِفَةٌ وَمُضَافٌ</span><span class="rule-table-ru">определение и первый член идафы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">حَامِدٍ</span><span class="rule-table-ru">Хамида</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">второй член идафы в родительном падеже; признак — явная касра</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ</span><span class="rule-table-ru">второй член идафы</span></td></tr></tbody></table></div></div></div>', 9, 'rule', 'Хамза слова «ибн» удаляется на письме, когда оно служит определением между именами сына и отца и все три слова находятся на одной строке; шарх перечисляет три случая сохранения хамзы.', 'تُحْذَفُ هَمْزَةُ ٱبْنٍ إِذَا وَقَعَتِ الْكَلِمَةُ صِفَةً بَيْنَ عَلَمَيْنِ، الْأَوَّلُ الِابْنُ وَالثَّانِي الْأَبُ، وَكَانَتِ الْكَلِمَاتُ الثَّلَاثُ فِي سَطْرٍ وَاحِدٍ. وَلَا تُحْذَفُ إِذَا لَمْ تَقَعْ صِفَةً، أَوْ جَاءَتْ فِي أَوَّلِ السَّطْرِ، أَوْ لَمْ تَقَعْ بَيْنَ عَلَمَيْنِ.');

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'ثَانِياً : بَـابُ أَفْعَلَ
مِنْ أمثلته : أَسْلَمَ ، أَجَابَ ، أَتَمَّ ، آمَنَ .
حرفُ الزَّيادةِ : الهمزة في أوَّله .
مَصْدَرُهُ : إِفْعَالٌ ، نحو : أَسْلَمَ : إِسْلاَمٌ . أََتَمَّ : إِتْمَامٌ . آمَنَ : إِيمَانٌ ( أصله إئْمَان ) قُلبت الهمزة ياء ؛ لأنها ساكنة وما قبلها مكسور .
فإن كان الفعلُ معتلَّ الفاء ، نحو ( أَوْجَدَ ) فمصدره ( إِيجَادٌ ) والأصل ( إِوْجَادٌ ) بِقَلْبِ الواو ياءً ؛ لأنها ساكنة وما قبلها مكسور ، والكسر يُناسبه الياء .
وإن كان الفعل معتلّ العين ، نحو ( أَجَابَ ) فمصدره ( إِجَابَةٌ ) والأصل (إِجْوَابٌ) بحذف عين المصدر ( الواو ) والتَّعويض بتاء التَّأنيث .
أما إن كان الفعل معتلّ اللاَّم ، نحو ( أَلْقَى ) فمصدره ( إِلْقَاءٌ ) والأصل ( إِلْقَايٌ ) بِقَلْبِ الياء همزة ؛ لأنّ الياء وقعت مُتَطَرَّفة وقبلها ألف زائدة .', 68, 69, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17' and sort_order = 1;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', '* جدولٌ يُبَيَّنُ مُشتقاتِ بابِ أَفْعَلَ
