أَكْرَم : أُكْرِمُ        أصله : أُأَكْرِمُ . حُذِفَتْ همزة المضارع ؛ كراهة اجتماع همزتين ، وحُمِلَ ذلك على بَقِيَّة التَّصَارِيف ، نحو : يُكْرِمُ ، ونُكْرِمُ ، وتُكْرِمُ ، ومُكْرِمٌ ، ومُكْرَمٌ .', 69, 69, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17' and sort_order = 2;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'أَعْطَى
أَعْطَى : مِنْ باب أَفْعَلَ . يَنْصِبُ مفعولين ليس أصلهما المبتدأ والخبر ، نحو :
أعطيتُ حامداً كتاباً       .                     أَعْطَانِيـهِ        المـديرُ
مفعول به أوَّل  مفعول به ثانٍ         مفعول به أوّل   مفعول به ثانٍ    فاعل مرفوع
منصوب       منصوب             في محل نصب     في محل نصب', 69, 69, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17' and sort_order = 3;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'أَصْبَحَ
أَصْبَحَ : مِن باب أَفْعَلَ . مِن أخوات كان يرفع الاسم وينصب الخبر ، نحو :
أصبح حامدٌ مريضاً ، بمعنى : أَدْرَكَهُ الصَّبَاحُ وهو مريضٌ .
قال تعالى : ﴿ وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَى فَارِغًا ﴾ ونحو : أصبحَ البردُ شديداً .
* قد تأتي ( أصبح ) بمعنى ( صَارَ ) قال تعالى : ﴿ فَأَصْبَحْتُمْ بِنِعْمَتِهِ إِخْوَانًا ﴾ أي : صِرْتُمْ إِخواناً .', 69, 70, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17' and sort_order = 4;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'أَوْشَكَ
أَوْشَكَ: مِن باب أَفْعَلَ . مِن أفعالِ الْمُقَارَبَةِ . تعملُ عَمَلَ كان ترفع الاسم، وتنصب الخبر إلاَّ أَنَّ خبرها لا يكون إلا جملة فعليّة فعلُها مضارعٌ مُقْتَرِنٌ بـ ( أَنْ ) المصدريَّة .
الأمثلة :
أَوْشَكَ المطرُ أَنْ يَنْزِلَ .                    يُوشِكُ الطُّلابُ أَنْ يَتَخَرَّجُوا .
الإعراب :
أوشك الدرسُ أن ينتهيَ .
أوشكَ : فعل ماضٍ ناقص مبني على الفتح .
الدرسُ : اسم أوشك مرفوع وعلامة رفعه الضمة الظاهرة .
أنْ ينتهيَ : أَنْ : حرف نصب ومصدر مبني على السكون .
ينتهيَ : فعل مضارع منصوب بـ ( أن ) وعلامة نصبه الفتحة الظاهرة،
والمصدر المؤوَّل ( أن ينتهي ) في محل نصب خبر أوشكَ .', 70, 70, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17' and sort_order = 5;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'وَلَوْ
قال تعالى : ﴿ وَاللَّهُ مُتِمُّ نُورِهِ وَلَوْ كَرِهَ الْكَافِرُونَ ﴾ .
وَلَوْ : الواو : للحال حرف مبني على الفتح لا محلَّ له من الإعراب .
لو : حرف شرط غير جازم مبني على السكون .
كَرِهَ : فعل الشرط فعل ماضٍ مبني على الفتح ، وجواب الشرط محذوف .
والتقدير : ولو كَرِهَ الكافرون فإنَّ اللهَ مُتِمُّ نورِه  .
وجملة الشرط ( لو كره الكافرون ) في محل نصب حال .
ومن الأمثلة قولك : صَلَِّ ولو كنت مريضاً . لن أشرب الخمرَ ولو عَذَّبْتَنِي .', 70, 71, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17' and sort_order = 6;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'لاَمُ الابْتِدَاءِ
لامُ الابتداءِ : حرفُ ابْتِدَاءٍ ؛ لأَِنَّها تقعُ في ابتداءِ الكلامِ .
فائدتها : التَّوكيدُ ، فهي تُؤَكَّد مَضْمُونَ الجملةِ .
الأمثلة :
قال تعالى : ﴿ وَلَأَجْرُ الْآخِرَةِ أَكْبَرُ ﴾ وقال تعالى : ﴿ وَلَذِكْرُ اللَّهِ أَكْبَرُ ﴾ .
ونحو : لَهَذَا طالبٌ مجتهدٌ .              لَفَاطمةُ مُؤْمنةٌ .
الإعراب : لمحمدٌ مجتهدٌ
اللاَّم : حرف ابتداء مبني على الفتح لا محلّ له من الإعراب .
محمدٌ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة .
مجتهدٌ : خبر مرفوع وعلامة رفعه الضمة الظاهرة .', 71, 71, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17' and sort_order = 7;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'مَا النَّكِرَةُ التَّامَّةُ الْمُبْهَمَةُ
ما النَّكرةُ التَّامَّةُ المبهمةُ : اسمٌ مبنيٌ على السكون يقعُ نعتاً لِمَا قَبْلَه ، نحو :
حَدَثَ شيءٌ ما .         أَعطني كتاباً ما .             رأيتُه في مكانٍ ما .
في محل رفع              في محل نصب                  في محل جر
نعت                      نعت                          نعت', 71, 72, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17' and sort_order = 8;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'حَذْفُ همزةِ ( ابْن )
تحذفُ همزةُ ( ابن ) في الحالة الآتية :
إذا وَقَعَتْ صِفةً بين عَلَمَيْنِ ( الابن ،والأب ) وأن تكونَ الكلماتُ الثَّلاثُ في سطرٍ واحدٍ، نحو : هذا محمدُ بنُ عبدِ اللهِ بنِ عبدِ الْمُطَّلِبِ . رأيت سعيدَ بنَ حامدٍ .
سلَّمت على خالدِ بنِ عليًّ .
ولا تُحْذَف في الحالات الآتية :
1- إذا لم تقع صِفَةً ، نحو : حامدٌ ابنُ عليًّ   .   خبر مرفوع .
2- إذا جاءت كلمة ابن في أول السطر ولو كانت بين عَلَمَيْنِ ، نحو : رأيتُ محمدَ
ابنَ سعيدٍ .
3- إذا لم تقع بين عَلَمَيْنِ، نحو : حامدٌ ابنُ الشَّيخِ إبراهيمَ . كلمة (الشَّيخ) ليست علماً.
الإعراب : هذا محمدُ بنُ حامدٍ .
هذا : اسم إشارة مبني على السكون في محل رفع مبتدأ .
محمدُ : خبر مرفوع وعلامة رفعه الضمة الظاهرة . ( حُذف تنوينه تَخْفِيفاً ) .
بنُ   : صفة مرفوعة وعلامة رفعها الضمة الظاهرة ، وهو مضاف .
حامدٍ : مضاف إليه مجرور وعلامة جرّه الكسرة الظاهرة .', 72, 73, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '17' and sort_order = 9;

